-- Изчисляване на средните оценки (това, което тригерът прави при нормална работа)
UPDATE a
SET a.AvgRating   = r.AvgScore,
    a.RatingCount = ISNULL(r.Cnt, 0)
FROM dbo.Anime a
OUTER APPLY (SELECT CAST(AVG(CAST(Score AS DECIMAL(5,2))) AS DECIMAL(3,2)) AS AvgScore, COUNT(*) AS Cnt
             FROM dbo.Ratings x WHERE x.AnimeID = a.AnimeID) r;
GO

ENABLE TRIGGER ALL ON dbo.Ratings;
ENABLE TRIGGER ALL ON dbo.WatchHistory;
ENABLE TRIGGER ALL ON dbo.Subscriptions;
ENABLE TRIGGER ALL ON dbo.Payments;
GO

-- Проверка: не трябва да има гледани премиум епизоди без премиум абонамент
SELECT COUNT(*) AS PremiumViolations
FROM dbo.WatchHistory w
JOIN dbo.Episodes e ON e.EpisodeID = w.EpisodeID
WHERE e.IsPremium = 1
  AND NOT EXISTS (
      SELECT 1
      FROM dbo.Subscriptions s
      JOIN dbo.SubscriptionPlans p ON p.PlanID = s.PlanID
      WHERE s.UserID = w.UserID
        AND p.PremiumAccess = 1
        AND s.StartDate <= CAST(w.WatchedAt AS DATE)
        AND (s.EndDate IS NULL OR s.EndDate >= CAST(w.WatchedAt AS DATE))
  );

-- Брой редове по таблици
SELECT t.name AS TableName, SUM(p.rows) AS [Rows]
FROM sys.tables t
JOIN sys.partitions p ON p.object_id = t.object_id AND p.index_id IN (0, 1)
GROUP BY t.name
ORDER BY t.name;
GO
